<?php require_once '../../conexion.php'; 
$sql = "SELECT d.*, m.nombre as mat_nombre, o.nro_orden_cotizacion FROM detalle_orden_compra d LEFT JOIN materia_prima m ON d.id_materia = m.ID LEFT JOIN orden_compra o ON d.id_orden_compra = o.ID ORDER BY d.ID DESC"; 
$detalles = $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); 
$ordenes = $pdo->query("SELECT o.ID, o.nro_orden_cotizacion, c.nombre as cli_nom FROM orden_compra o LEFT JOIN cliente c ON o.id_cliente=c.ID ORDER BY o.ID DESC")->fetchAll(PDO::FETCH_ASSOC);
$materias = $pdo->query("SELECT ID, nombre, color FROM materia_prima ORDER BY nombre ASC")->fetchAll(PDO::FETCH_ASSOC);
?>
