    <main class="main-content" style="padding-right: 10px;"><header class="header"><h1>Renglones de Órdenes (Prendas)</h1><div class="search-bar"><input type="text" id="buscador" onkeyup="buscarTabla()" placeholder="Buscar prenda o Nro Orden..."></div></header>
        <div class="card" style="overflow-x:auto;"><div class="card-header"><h3>Total: <?= count($detalles) ?> prendas</h3><div style="display:flex;gap:10px;"><button class="btn btn-report" onclick="window.open('reporte.php','_blank')"><i class="ph-bold ph-printer"></i> Imprimir</button><button class="btn btn-primary" onclick="agregarFilaVacia()"><i class="ph-bold ph-plus"></i> Añadir Prenda</button></div></div>
