                        <td data-campo="id_materia" data-idval="<?= $d['id_materia'] ?>" data-text="<?= htmlspecialchars($d['mat_nombre'] ?? 'N/A') ?>" style="color:var(--color-green); font-weight:600;"><?= htmlspecialchars($d['mat_nombre'] ?? 'N/A') ?></td>
                        <td data-campo="tipo_prenda"><?= htmlspecialchars($d['tipo_prenda'] ?? '') ?></td><td data-campo="talla"><?= htmlspecialchars($d['talla'] ?? '') ?></td><td data-campo="cantidad"><?= htmlspecialchars($d['cantidad'] ?? '0') ?></td><td data-campo="precio_unitario"><?= htmlspecialchars($d['precio_unitario'] ?? '0.00') ?></td><td data-campo="detalle_diseno"><?= htmlspecialchars($d['detalle_diseno'] ?? '') ?></td><td data-campo="combinacion_colores"><?= htmlspecialchars($d['combinacion_colores'] ?? '') ?></td>
                        <td style="text-align:center;white-space:nowrap; position:sticky; right:0; background:var(--main-bg);"><button class="action-btn" onclick="editarFila('<?= $d['ID'] ?>')"><i class="ph-fill ph-pencil-simple"></i></button> <button class="action-btn text-red" onclick="eliminarFila('<?= $d['ID'] ?>')"><i class="ph-fill ph-trash"></i></button> <button class="action-btn text-green" onclick="guardarFila('<?= $d['ID'] ?>')" id="btn-save-<?= $d['ID'] ?>" style="display:none;"><i class="ph-bold ph-check"></i></button> <button class="action-btn text-red" onclick="cancelarEdicion('<?= $d['ID'] ?>')" id="btn-cancel-<?= $d['ID'] ?>" style="display:none;"><i class="ph-bold ph-x"></i></button></td></tr>
