        <?php foreach($materias as $m): ?><tr><td><?= $m['ID'] ?></td><td style="font-weight:bold;"><?= htmlspecialchars($m['nombre']) ?></td><td><?= htmlspecialchars($m['color']) ?></td><td style="text-align:right;"><button class="btn-elegir" onclick="seleccionarItem('id_materia', '<?= $m['ID'] ?>', '<?= addslashes(htmlspecialchars($m['nombre'])) ?>', 'modalMat')">Elegir</button></td></tr><?php endforeach; ?>
    </tbody></table></div></div></div>

    <script>
        let datosOrig={}; let filaActivaModal=null; const campos=['id_orden_compra','id_materia','tipo_prenda','talla','cantidad','precio_unitario','detalle_diseno','combinacion_colores'];
        function abrirModal(mId, idFila) { filaActivaModal = idFila; document.querySelectorAll('.modal-overlay').forEach(m=>m.style.display='none'); document.getElementById(mId).style.display='flex'; } function cerrarModal(mId) { document.querySelectorAll('.modal-overlay').forEach(m=>m.style.display='none'); }
        function seleccionarItem(c, idVal, txtVal) { document.getElementById(`input-${filaActivaModal}-${c}`).value=idVal; document.getElementById(`text-${filaActivaModal}-${c}`).innerText=txtVal; cerrarModal(c==='id_orden_compra'?'modalOrd':'modalMat'); }
        function filtrarLista(inp, tab) { let f=document.getElementById(inp).value.toLowerCase(), r=document.getElementById(tab).getElementsByTagName('tbody')[0].getElementsByTagName('tr'); for(let i=0; i<r.length; i++) r[i].style.display = r[i].innerText.toLowerCase().includes(f) ? "" : "none"; }
        
        function editarFila(id){datosOrig[id]={};document.querySelectorAll(`#row-${id} td[data-campo]`).forEach(td=>{let c=td.getAttribute('data-campo');datosOrig[id][c]=td.innerHTML; if(c==='id_orden_compra'||c==='id_materia'){let m=c==='id_orden_compra'?'modalOrd':'modalMat'; td.innerHTML=`<div class="selector-box" onclick="abrirModal('${m}', '${id}')"><span id="text-${id}-${c}">${td.getAttribute('data-text')}</span> <i class="ph-bold ph-caret-down"></i></div><input type="hidden" id="input-${id}-${c}" value="${td.getAttribute('data-idval')}">`;}else{let type=c==='cantidad'?'number':(c==='precio_unitario'?'number" step="0.01':'text');td.innerHTML=`<input type="${type}" class="form-control" id="input-${id}-${c}" value="${td.innerText}">`;}});document.getElementById(`btn-edit-${id}`).style.display='none';document.getElementById(`btn-save-${id}`).style.display='inline-block';document.getElementById(`btn-cancel-${id}`).style.display='inline-block';}
        function cancelarEdicion(id){if(id==='nuevo')return document.getElementById('row-nuevo').remove();document.querySelectorAll(`#row-${id} td[data-campo]`).forEach(td=>td.innerHTML=datosOrig[id][td.getAttribute('data-campo')]);document.getElementById(`btn-edit-${id}`).style.display='inline-block';document.getElementById(`btn-save-${id}`).style.display='none';document.getElementById(`btn-cancel-${id}`).style.display='none';}
        function agregarFilaVacia(){if(document.getElementById('row-nuevo'))return;let tr=document.createElement('tr');tr.id='row-nuevo';tr.style.backgroundColor='#f0fdf4';tr.innerHTML=`<td>Nuevo</td><td data-campo="id_orden_compra"><div class="selector-box" onclick="abrirModal('modalOrd', 'nuevo')"><span id="text-nuevo-id_orden_compra">🔍 Elegir Orden...</span></div><input type="hidden" id="input-nuevo-id_orden_compra"></td><td data-campo="id_materia"><div class="selector-box" onclick="abrirModal('modalMat', 'nuevo')"><span id="text-nuevo-id_materia">🔍 Elegir Tela...</span></div><input type="hidden" id="input-nuevo-id_materia"></td><td data-campo="tipo_prenda"><input type="text" class="form-control" id="input-nuevo-tipo_prenda"></td><td data-campo="talla"><input type="text" class="form-control" id="input-nuevo-talla"></td><td data-campo="cantidad"><input type="number" class="form-control" id="input-nuevo-cantidad"></td><td data-campo="precio_unitario"><input type="number" step="0.01" class="form-control" id="input-nuevo-precio_unitario"></td><td data-campo="detalle_diseno"><input type="text" class="form-control" id="input-nuevo-detalle_diseno"></td><td data-campo="combinacion_colores"><input type="text" class="form-control" id="input-nuevo-combinacion_colores"></td><td style="text-align:center; position:sticky; right:0; background:#f0fdf4;"><button class="action-btn text-green" onclick="guardarFila('nuevo')"><i class="ph-bold ph-check"></i></button> <button class="action-btn text-red" onclick="cancelarEdicion('nuevo')"><i class="ph-bold ph-x"></i></button></td>`;document.getElementById('cuerpoTabla').prepend(tr);}
        function guardarFila(id){let o=document.getElementById(`input-${id}-id_orden_compra`).value, m=document.getElementById(`input-${id}-id_materia`).value; if(!o||!m){Swal.fire('Alto','Selecciona Orden y Material','warning');return;} let fd=new FormData();fd.append('accion',id==='nuevo'?'crear':'editar');if(id!=='nuevo')fd.append('id',id);campos.forEach(c=>fd.append(c,document.getElementById(`input-${id}-${c}`).value));fetch('crud.php',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.status==='success')location.reload();});}
        function eliminarFila(id){Swal.fire({title:'¿Borrar?',icon:'warning',showCancelButton:true,confirmButtonColor:'#E11D48'}).then((r)=>{if(r.isConfirmed){let fd=new FormData();fd.append('accion','eliminar');fd.append('id',id);fetch('crud.php',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.status==='success')location.reload();});}});}
        function buscarTabla(){let i=document.getElementById("buscador").value.toLowerCase();document.querySelectorAll("#tablaDatos tbody tr").forEach(tr=>{if(tr.id!=='row-nuevo')tr.style.display=tr.innerText.toLowerCase().includes(i)?"":"none";});}
    </script>
</body></html>